  for(const c of current.chests){if(c.open)continue;const near=Math.hypot(G.p.x-c.x,G.p.y-c.y)<25;c.hold=near?c.hold+Math.min(dt,.05):0;if(c.hold>.6)pnInnerLoot(c);}
